#!/usr/bin/env python3
"""
Script to convert nybbles data from 0.3 format to 0.4+ format.

In nybbles 0.3: nibbles were serialized as arrays of numbers (one nibble per array element)
In nybbles 0.4+: nibbles are serialized as hex strings with "0x" prefix

This script converts the nibbles fields from the old array format to the new hex string format.
"""

import json
import binascii
import re

# Your original serialized proof hex (replace with your actual data)
serialized_proof_hex = "";
# Step 1: remove 0x
hex_str = serialized_proof_hex[2:]

# Step 2: hex decode
raw_bytes = binascii.unhexlify(hex_str)

# Step 3: decode to string and clean it
json_str = raw_bytes.decode("utf-8", errors='ignore')  # Ignore invalid UTF-8 characters

# Remove all control characters (ASCII 0-31) except standard whitespace (\t, \n, \r, space)
json_str = re.sub(r'[\x00-\x08\x0b-\x1f\x7f-\x9f]', '', json_str)
print("Raw JSON string (cleaned):")
print(json_str)
print("\n" + "="*50 + "\n")

# Step 4: parse JSON
try:
    proof_obj = json.loads(json_str)
except json.JSONDecodeError as e:
    print(f"JSON decode error: {e}")
    print(f"Error at position: {e.pos}")
    print(f"Character around error: {repr(json_str[e.pos-10:e.pos+10])}")
    exit(1)

# Step 5: Convert nibbles from old format (array) to new format (hex string)
def convert_nibbles_to_hex(nibbles_array):
    """
    Convert nibbles array (0.3 format) to hex string (0.4+ format)
    
    In 0.3: nibbles were stored as [10, 11, 12, 13] (decimal values 0-15)
    In 0.4+: nibbles are stored as "0xabcd" (hex string)
    """
    if not isinstance(nibbles_array, list):
        # Already in new format, return as-is
        return nibbles_array
    
    # Convert each nibble (0-15) to hex character
    hex_chars = []
    for nibble in nibbles_array:
        if not isinstance(nibble, int) or nibble < 0 or nibble > 15:
            print(f"Warning: Invalid nibble value {nibble}, skipping conversion")
            return nibbles_array
        hex_chars.append(f"{nibble:x}")
    
    # Join all hex characters and add 0x prefix
    if len(hex_chars) == 0:
        return "0x"
    else:
        return f"0x{''.join(hex_chars)}"

# Step 6: Find and convert all nibbles fields
def convert_nibbles_recursive(obj):
    """Recursively find and convert all 'nibbles' fields in the JSON structure"""
    if isinstance(obj, dict):
        for key, value in obj.items():
            if key == 'nibbles' and isinstance(value, list):
                # Check if this looks like old format (array of integers 0-15)
                if all(isinstance(x, int) and 0 <= x <= 15 for x in value):
                    print(f"Converting nibbles field: {value} -> ", end="")
                    obj[key] = convert_nibbles_to_hex(value)
                    print(obj[key])
                else:
                    print(f"Nibbles field doesn't look like old format, leaving as-is: {value}")
            else:
                convert_nibbles_recursive(value)
    elif isinstance(obj, list):
        for item in obj:
            convert_nibbles_recursive(item)

# Convert all nibbles fields in the proof object
convert_nibbles_recursive(proof_obj)

# Step 7: Save updated JSON back to file
output_file = "res/storage_proof.json"
with open(output_file, "w") as f:
    json.dump(proof_obj, f, separators=(',', ':'))

print(f"✅ Successfully updated {output_file} with nibbles as hex strings!")

# Step 8: Convert back to JSON string for display
new_json_str = json.dumps(proof_obj, separators=(',', ':'))

# Step 9: Convert to bytes and then to hex
new_raw_bytes = new_json_str.encode("utf-8")
new_hex_str = binascii.hexlify(new_raw_bytes).decode("utf-8")

# Step 10: Add 0x prefix and print result
final_result = f"0x{new_hex_str}"
print("\nUpdated proof with nibbles as hex strings:")
print(final_result)
print(f"\nSize: {len(final_result)} characters")
print(f"Hex data size: {len(final_result)//2} bytes")

# Step 11: Show the differences
print("\n" + "="*50)
print("CONVERSION SUMMARY:")
print("="*50)
print("✅ Converted nibbles from 0.3 format (array) to 0.4+ format (hex string)")
print("✅ Old format: [10, 11, 12, 13] -> New format: \"0xabcd\"")
print("✅ All nibbles fields have been updated to the new format")
